\begin{theorem} \label{thm:xj_speed_higher_order}
        Let $f : \R^n \rightarrow \R$ be locally Lipschitz continuous. Let $(x^j)_j \in \R^n$, $(\eps_j)_j \in \R^{\geq 0}$ and $(\delta_j)_j \in \R^{\geq 0}$ such that $x^j \rightarrow x^* \in \R^n$, $\eps_j \rightarrow 0$ and $\min(\| \partial_{\eps_j} f(x^j) \|) \leq \delta_j$ for all $j \in \N$.
        Assume that $x^*$ is a minimum of order $p \in \N$ with constant $\beta > 0$ and that \eqref{eq:p_order_min_semismooth} holds in $x^*$.
        \begin{enumerate}
            \item[(i)] If $p = 1$ and $\delta_j \rightarrow \Bar{\delta} < \beta$, then there are $M > 0$ and $N \in \N$ such that
            \begin{align} \label{eq:xj_speed_higher_order_1}
                \| x^j - x^* \| \leq M \eps_j \quad \forall j > N.
            \end{align}
            \item[(ii)] If $p \geq 2$ then there are $M > 0$ and $N \in \N$ such that
            \begin{align} \label{eq:xj_speed_higher_order_2}
                \| x^j - x^* \| \leq M \max(\eps_j^{\frac{1}{p}}, \delta_j^{\frac{1}{p-1}}) \quad \forall j > N.
            \end{align}
        \end{enumerate}
    \end{theorem}

\begin{proof}
        Assume that (i) or (ii) do not hold. Then in both cases there is a subsequence $(j_l)_l \in \N$ with $x^{j_l} \neq x^*$ for all $l \in \N$,
        \begin{align} \label{eq:proof_thm_xj_speed_higher_order_1}
            \lim_{l \rightarrow \infty} \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|^{p}} = 0
            \quad \text{and} \quad
             \lim_{l \rightarrow \infty} \frac{\delta_{j_l}}{\| x^{j_l} - x^* \|^{p-1}} < \beta.
        \end{align}
        (In case (ii) does not hold, the second limit actually vanishes.) \\
        \textbf{Step 1:} For $l \in \N$ let $g^l \in \partial_{\eps_{j_l}} f(x^{j_l})$ with $\| g^l \| \leq \delta_{j_l}$. By Carathéodory's theorem, for $i \in \{1,\dots,n+1\}$, there are $y_i^l \in \Bcl_{\eps_{j_l}}(x^{j_l})$, $\xi_i^l \in \partial f(y_i^l) \subseteq \partial_{\eps_{j_l}} f(x^{j_l})$ and $\alpha_i^l \geq 0$ with $\sum_{i = 1}^{n+1} \alpha_i^l = 1$ and
        \begin{align*}
            g^l = \sum_{i = 1}^{n+1} \alpha_i^l \xi_i^l.
        \end{align*}
        Since $\| y_i^l - x^{j_l} \| \leq \eps_{j_l}$ it holds $\lim_{l \rightarrow \infty} y_i^l = x^*$ for all $i \in \{1,\dots,n+1\}$. By compactness of the $\eps$-subdifferential at $x^*$ (cf. \cite{G1977}, Proposition 2.3), we can assume w.l.o.g. that $\lim_{l \rightarrow \infty} \xi_i^l = \Bar{\xi}_i \in \R^n$ for all $i \in \{1,\dots,n+1\}$. By \cite{C1990}, Proposition 2.1.5, it follows that $\Bar{\xi}_i \in \partial f(x^*)$. Furthermore, by compactness of the set of convex coefficients, we can assume w.l.o.g. that $\lim_{l \rightarrow \infty} \alpha_i^l = \Bar{\alpha}_i$ for all $i \in \{1,\dots,n+1\}$, such that
        \begin{align*}
            \Bar{g} := \sum_{i = 1}^{n+1} \Bar{\alpha}_i \Bar{\xi}_i \in \partial f(x^*)
        \end{align*}
        is the limit of $(g^l)_l$. (In case (ii) we have $\Bar{g} = 0$.) \\
        \textbf{Step 2:} Consider the sequences $(d^l)_l$ and $(d_i^l)_l$ given by
        \begin{align*}
            d^l := \frac{x^{j_l} - x^*}{\| x^{j_l} - x^* \|} \quad \text{and} \quad d_i^l := \frac{y_i^l - x^*}{\| x^{j_l} - x^* \|}, \ i \in \{1,\dots,n+1\}.
        \end{align*}
        By compactness, $(d^l)_l$ must have an accumulation point $\Bar{d} \in \R^n$ with $\| \Bar{d} \| = 1$. Assume w.l.o.g. that $\Bar{d}$ is the limit of $(d^l)_l$. 
        For all $i \in \{1,\dots,n+1\}$, it holds
        \begin{align*}
            \| d_i^l - d^l \| 
            = \frac{\| y_i^l - x^* - (x^{j_l} - x^*) \|}{\| x^{j_l} - x^* \|}
            = \frac{\| y_i^l - x^{j_l} \|}{\| x^{j_l} - x^* \|}
            \leq \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|},
        \end{align*}
        and combined with \eqref{eq:proof_thm_xj_speed_higher_order_1}, we obtain
        \begin{align} \label{eq:proof_thm_xj_speed_higher_order_2}
            \frac{\| d_i^l - d^l \|}{\| x^{j_l} - x^* \|^{p-1}} \leq \frac{\eps_{j_l}}{\| x^{j_l} - x^* \|^{p}} \xrightarrow[]{l \rightarrow \infty} 0.
        \end{align}
        In particular, $\lim_{l \rightarrow \infty} d_i^l = \bar{d}$ for all $i \in \{1,\dots,n+1\}$.\\ 
        \textbf{Step 3:} By construction we have 
        \begin{align*}
            \xi_i^l \in \partial f(y_i^l) 
            = \partial f \left( x^* + \| x^{j_l} - x^* \| \frac{y_i^l - x^*}{\| x^{j_l} - x^* \|} \right) 
            = \partial f(x^* + \| x^{j_l} - x^* \| d_i^l).
        \end{align*}
